INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7759560, 1284837, 30861, '<td valign="top">LOVE the blur of the drooping leaves :-) Wonderful image.First one on my voting screen, first 9 from me. May end up as a 10, we''ll see :-)</td>', 'LOVE the blur of the drooping leaves :-) Wonderful image.First one on my voting screen, first 9 from me. May end up as a 10, we''ll see :-)', '2023-11-01 09:56:21.000000', NULL, 1),
(7759561, 1284901, 30861, '<td valign="top">It couldn''t be any better, could it? I''m looking for a nit to pick. Yay, I found one! Two actually :-) I wish I could see the horse''s eye rolling, and I think I see a bit of awkward masking at the butt end of things. But I had to work hard for those nits! Well done! 9 for now.</td>', 'It couldn''t be any better, could it? I''m looking for a nit to pick. Yay, I found one! Two actually :-) I wish I could see the horse''s eye rolling, and I think I see a bit of awkward masking at the butt end of things. But I had to work hard for those nits! Well done! 9 for now.', '2023-11-01 09:59:55.000000', NULL, 1),
(7759562, 1284796, 30861, '<td valign="top">He sure is! Speaking of which, I just came across an X-ray profile view of an entire turtle and realized, to my amazement, that the "shells" are part of their skeletal structure. In other words, you can''t remove a turtle or tortoise from its shell. I don''t know why that surprised me, but it was an aha moment. I digress. Wonderful image!</td>', 'He sure is! Speaking of which, I just came across an X-ray profile view of an entire turtle and realized, to my amazement, that the "shells" are part of their skeletal structure. In other words, you can''t remove a turtle or tortoise from its shell. I don''t know why that surprised me, but it was an aha moment. I digress. Wonderful image!', '2023-11-01 10:03:31.000000', NULL, 1),
(7759563, 1284823, 30861, '<td valign="top">Stupendous layering! Absolutely gorgeously seen and rendered!</td>', 'Stupendous layering! Absolutely gorgeously seen and rendered!', '2023-11-01 10:04:56.000000', NULL, 1),
(7759564, 1284874, 30861, '<td valign="top">This is SO weird! Enticingly so. Major props for *seeing* this one!</td>', 'This is SO weird! Enticingly so. Major props for *seeing* this one!', '2023-11-01 10:06:14.000000', NULL, 1),
(7759565, 1284872, 30861, '<td valign="top">Mais oui!</td>', 'Mais oui!', '2023-11-01 10:07:48.000000', NULL, 1),
(7759566, 1284896, 30861, '<td valign="top">Holy smokes! I can''t wait to find out where this is. Beautifully rendered!</td>', 'Holy smokes! I can''t wait to find out where this is. Beautifully rendered!', '2023-11-01 10:10:29.000000', NULL, 1),
(7759569, 1284722, 30861, '<td valign="top">My lord, that''s a blast from the past of warship design :-) I''m amazed by the hard chines and the fared rudder opening. Wonderful shot. I''m a ship-junkie. Feel free to let me know what ship this is and where it''s at, I''ve already given your 8 :-)<br/> <br/>Ah, I got it. That''s USS Texas drydocked in Galveston :-) Which means this just be a Spiffy shot?</td>', 'My lord, that''s a blast from the past of warship design :-) I''m amazed by the hard chines and the fared rudder opening. Wonderful shot. I''m a ship-junkie. Feel free to let me know what ship this is and where it''s at, I''ve already given your 8 :-) Ah, I got it. That''s USS Texas drydocked in Galveston :-) Which means this just be a Spiffy shot?', '2023-11-01 10:19:52.000000', NULL, 1),
